//! The Kata agent policy of a confidential pod: generated by genpolicy 4.1.0 under our settings,
//! then held to the PRD-02 baseline before it goes into the init-data.
//!
//! genpolicy's output is its rules file followed by `policy_data`, the per-pod data those rules
//! read. The rules here are genpolicy 4.1.0's own, byte for byte, so a policy is accepted only as
//! those rules plus data, and the baseline is a property of the data: exec, log reads and stdin
//! refused, file copies only into the shared-files prefix, images pulled in the guest and pinned by
//! digest, and no environment variable the host may add beyond the two listed below. A policy
//! that edits the rules, or whose data loosens any of that, is refused rather than repaired.

use std::collections::BTreeSet;
use std::os::unix::fs::DirBuilderExt;
use std::path::{Path, PathBuf};
use std::process::Stdio;
use std::time::Duration;

pub use alpha_core::coco::policy::{
    ALLOWED_ENV_REGEX, COPY_FILE_PATHS, DSM_ENV, KMS_ENDPOINTS_ENV_REGEX, PolicyContainer,
    REFUSED_REQUESTS, RULES, Verified, dsm_pinned, verify,
};
#[cfg(test)]
use alpha_core::coco::policy::{
    DATA_PREFIX, IMAGE_ANNOTATION, NAME_ANNOTATION, TOKEN_MOUNTS, TYPE_ANNOTATION,
};
#[cfg(test)]
use serde_json::{Value, json};
use sha2::{Digest, Sha256};

/// Where the adapter image ships genpolicy 4.1.0, from kata-containers' release asset
/// `kata-tools-static-4.1.0-amd64.tar.zst` (sha256
/// 58fd166094b456d792b61eda218c44d3b4717281e0debd6869c8e787453f8f30), which installs it here.
pub const GENPOLICY_PATH: &str = "/opt/kata/bin/genpolicy";
/// SHA-256 of that `genpolicy` binary; any other file at the path is refused before it runs.
pub const GENPOLICY_SHA256: &str =
    "c32ad5371d0c348100edf76758ce56682b2868fb250b883d2c7f0a68c342aa59";
/// genpolicy 4.1.0's `rules.rego` (from the same tarball), as released.
/// genpolicy 4.1.0's default `genpolicy-settings.json`, as released.
const UPSTREAM_SETTINGS: &str = include_str!("genpolicy/genpolicy-settings.json");
/// The settings drop-ins genpolicy applies to its defaults (RFC 6902 patches, in name order):
/// #82's Alpha baseline, byte for byte, and the KMS endpoints variable.
pub const SETTINGS_DROP_INS: [(&str, &str); 2] = [
    (
        "30-alpha-baseline.json",
        include_str!("genpolicy/genpolicy-settings.d/30-alpha-baseline.json"),
    ),
    (
        "40-alpha-kms-endpoints.json",
        include_str!("genpolicy/genpolicy-settings.d/40-alpha-kms-endpoints.json"),
    ),
];
/// genpolicy reads the binary at most this large.
const MAX_GENPOLICY_BYTES: u64 = 64 << 20;
/// genpolicy's own output stays under the init-data limit.
const MAX_OUTPUT_BYTES: usize = alpha_core::coco::MAX_INITDATA_BYTES;

/// genpolicy's settings directory, as (path, contents): its default `genpolicy-settings.json`
/// and the drop-ins under `genpolicy-settings.d/`, which genpolicy applies itself.
pub fn settings_files() -> Vec<(String, &'static str)> {
    let mut files = vec![("genpolicy-settings.json".to_owned(), UPSTREAM_SETTINGS)];
    files.extend(
        SETTINGS_DROP_INS
            .iter()
            .map(|(name, text)| (format!("genpolicy-settings.d/{name}"), *text)),
    );
    files
}

/// Why genpolicy did not produce a policy.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum GenpolicyError {
    /// The container's user comes from its image's `/etc/passwd` and `/etc/group`, which a guest
    /// pull does not reproduce, so genpolicy wants them in the pod spec: the image's UID and
    /// primary GID, and its supplementary groups.
    Identity {
        container: String,
        uid: u32,
        gid: u32,
        groups: BTreeSet<u32>,
    },
    /// genpolicy could not read an image from its registry: private, missing, or not for
    /// linux/amd64. About the compose.
    Image(String),
    /// Anything else: about our setup (the binary, its settings, the pod spec we gave it).
    Failed(String),
}

/// What genpolicy 4.1.0's panics say when it cannot read an image (`registry.rs`).
const IMAGE_FAILURES: [&str; 4] = [
    "Failed to pull container image",
    "registry authentication failure",
    "Failed to decompress image layer",
    "Failed to get users from image layer",
];

/// genpolicy at a path, held to a SHA-256.
pub struct Genpolicy {
    pub path: PathBuf,
    pub sha256: String,
    /// The directory holding the release's `rules.rego` and `genpolicy-settings.json` beside the
    /// binary, checked against [`RELEASE_FILES`] so the image ships the 4.1.0 release that the
    /// embedded Alpha baseline was made from. `None` skips the check (tests that run a binary
    /// from elsewhere).
    pub defaults: Option<PathBuf>,
    pub timeout: Duration,
}

/// Where the adapter image (rafay-plugins' `rafay-integration/Dockerfile`) ships genpolicy's
/// release rules and settings, at Kata's own paths.
pub const GENPOLICY_DEFAULTS: &str = "/opt/kata/share/defaults/kata-containers";
/// The release files there and their sha256, the Dockerfile's pins. genpolicy runs with the
/// copies embedded in `alpha` with the Alpha baseline applied (the patched rules and the
/// drop-ins), which are made from exactly these bytes; the image's files are checked, not read
/// into the policy, so the image needs no baseline files of its own.
pub const RELEASE_FILES: [(&str, &str); 2] = [
    (
        "rules.rego",
        "a1ad4280a7d1db83649de18640fb30f08cc160fadd7f4360d1dde09977b090b7",
    ),
    (
        "genpolicy-settings.json",
        "46bf9ac5460393f626ff2ed6fa2501ec5a82893da57c06e5c53a8f8e50e9dfa0",
    ),
];

impl Genpolicy {
    /// The pinned binary at [`GENPOLICY_PATH`]. The adapter gives the whole wrap two minutes;
    /// genpolicy gets most of that, since it downloads every image layer to read
    /// `/etc/passwd` and `/etc/group`.
    pub fn pinned() -> Self {
        Self {
            path: PathBuf::from(GENPOLICY_PATH),
            sha256: GENPOLICY_SHA256.to_owned(),
            defaults: Some(PathBuf::from(GENPOLICY_DEFAULTS)),
            timeout: Duration::from_secs(100),
        }
    }

    /// Runs genpolicy on one Kubernetes resource and returns the policy it prints. It runs in a
    /// fresh directory of its own with an empty environment, under our rules and settings; the
    /// binary is hashed first and refused unless it is the pinned one. A path an attacker could
    /// swap between the hash and the exec is a path in the adapter image, which already holds
    /// `alpha` itself.
    pub async fn run(&self, resource_yaml: &str) -> Result<String, GenpolicyError> {
        let failed = |m: String| GenpolicyError::Failed(m);
        let binary = std::fs::File::open(&self.path)
            .and_then(|f| {
                let mut bytes = Vec::new();
                std::io::Read::read_to_end(
                    &mut std::io::Read::take(f, MAX_GENPOLICY_BYTES),
                    &mut bytes,
                )
                .map(|_| bytes)
            })
            .map_err(|e| failed(format!("genpolicy at {}: {e}", self.path.display())))?;
        let digest = hex::encode(Sha256::digest(&binary));
        if digest != self.sha256 {
            return Err(failed(format!(
                "genpolicy at {} has sha256 {digest}, not the pinned {}",
                self.path.display(),
                self.sha256
            )));
        }
        drop(binary);
        for (name, pinned) in self
            .defaults
            .iter()
            .flat_map(|d| RELEASE_FILES.map(|(n, h)| (d.join(n), h)))
        {
            let bytes =
                std::fs::read(&name).map_err(|e| failed(format!("{}: {e}", name.display())))?;
            let digest = hex::encode(Sha256::digest(&bytes));
            if digest != pinned {
                return Err(failed(format!(
                    "{} has sha256 {digest}, not the pinned {pinned}",
                    name.display()
                )));
            }
        }
        let dir = TempDir::new().map_err(failed)?;
        let settings_dir = dir.0.join("settings");
        let write = |path: &Path, text: &str| {
            std::fs::write(path, text).map_err(|e| failed(format!("{}: {e}", path.display())))
        };
        std::fs::create_dir(&settings_dir)
            .map_err(|e| failed(format!("{}: {e}", settings_dir.display())))?;
        std::fs::create_dir(settings_dir.join("genpolicy-settings.d"))
            .map_err(|e| failed(format!("{}: {e}", settings_dir.display())))?;
        for (path, text) in settings_files() {
            write(&settings_dir.join(path), text)?;
        }
        write(&dir.0.join("rules.rego"), RULES)?;
        write(&dir.0.join("resource.yaml"), resource_yaml)?;
        let run = tokio::process::Command::new(&self.path)
            .args([
                "--yaml-file",
                "resource.yaml",
                "--rego-rules-path",
                "rules.rego",
                "--json-settings-path",
                "settings",
                "--raw-out",
                "--use-cached-files",
                "--layers-cache-file-path=layers-cache.json",
            ])
            .env_clear()
            .current_dir(&dir.0)
            .stdin(Stdio::null())
            .kill_on_drop(true)
            .output();
        let output = tokio::time::timeout(self.timeout, run)
            .await
            .map_err(|_| failed(format!("genpolicy took over {:?}", self.timeout)))?
            .map_err(|e| failed(format!("genpolicy: {e}")))?;
        if !output.status.success() {
            let stderr = String::from_utf8_lossy(&output.stderr);
            // A panic's message is the line after "panicked at"; anything else, the last line.
            let mut lines = stderr.lines().filter(|l| !l.trim().is_empty());
            let reason = lines
                .clone()
                .skip_while(|l| !l.contains("panicked at"))
                .nth(1)
                .or_else(|| lines.next_back())
                .unwrap_or_default();
            let reason = format!("genpolicy exited with {}: {reason}", output.status);
            return Err(identity(&stderr).unwrap_or_else(|| {
                if IMAGE_FAILURES.iter().any(|m| stderr.contains(m)) {
                    GenpolicyError::Image(reason)
                } else {
                    failed(reason)
                }
            }));
        }
        if output.stdout.len() > MAX_OUTPUT_BYTES {
            return Err(failed("genpolicy printed a policy over 512 KiB".into()));
        }
        String::from_utf8(output.stdout).map_err(|_| failed("genpolicy printed non-UTF-8".into()))
    }
}

/// genpolicy 4.1.0's refusal of a container whose user it read from the image's layers
/// (`policy.rs`, "guest_pull is enabled for container ..."), parsed back into what it expects.
pub fn identity(stderr: &str) -> Option<GenpolicyError> {
    let rest = stderr
        .split_once("ERROR: guest_pull is enabled for container '")?
        .1;
    let (container, rest) = rest.split_once('\'')?;
    let rest = rest.split_once("expects UID=")?.1;
    let (uid, rest) = rest.split_once(", GID=")?;
    let (gid, rest) = rest.split_once(", AdditionalGids={")?;
    let groups = rest.split_once('}')?.0;
    let groups = groups
        .split(',')
        .map(str::trim)
        .filter(|g| !g.is_empty())
        .map(str::parse)
        .collect::<Result<BTreeSet<u32>, _>>()
        .ok()?;
    Some(GenpolicyError::Identity {
        container: container.to_owned(),
        uid: uid.parse().ok()?,
        gid: gid.parse().ok()?,
        groups,
    })
}

/// A directory only this process uses, removed with everything in it when dropped.
struct TempDir(PathBuf);

impl TempDir {
    fn new() -> Result<Self, String> {
        let name = format!("alpha-genpolicy-{}", hex::encode(crate::random::<16>()?));
        let path = std::env::temp_dir().join(name);
        std::fs::DirBuilder::new()
            .mode(0o700)
            .create(&path)
            .map_err(|e| format!("{}: {e}", path.display()))?;
        Ok(Self(path))
    }
}

impl Drop for TempDir {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.0);
    }
}

/// A policy that holds the baseline and admits exactly `containers` (name, image), in the form
/// genpolicy prints, for tests that need one without running genpolicy.
#[cfg(test)]
pub(crate) fn test_policy(containers: &[(&str, &str)]) -> String {
    let with_env: Vec<_> = containers.iter().map(|(n, i)| (*n, *i, &[][..])).collect();
    test_policy_env(&with_env)
}

/// As [`test_policy`], each container also listing an environment.
#[cfg(test)]
pub(crate) fn test_policy_env(containers: &[(&str, &str, &[&str])]) -> String {
    let mut data = tests::data();
    let mut list = vec![data["containers"][0].clone()];
    for (name, image, env) in containers {
        let mut c = data["containers"][1].clone();
        c["OCI"]["Annotations"][NAME_ANNOTATION] = json!(name);
        c["OCI"]["Annotations"][IMAGE_ANNOTATION] = json!(image);
        c["OCI"]["Process"] = json!({ "Env": env });
        list.push(c);
    }
    data["containers"] = json!(list);
    tests::policy(&data)
}

#[cfg(test)]
mod tests {
    use super::*;

    /// genpolicy 4.1.0's released `rules.rego`, vendored in alpha-core beside the patched rules.
    const UPSTREAM_RULES: &str = include_str!("../../../alpha-core/src/coco/genpolicy/rules.rego");

    /// A policy as genpolicy prints it, from `policy_data`.
    pub(crate) fn policy(data: &Value) -> String {
        format!(
            "{RULES}{DATA_PREFIX}{}",
            serde_json::to_string_pretty(data).unwrap()
        )
    }

    /// genpolicy's settings once it has applied the drop-ins (RFC 6902; the operations they use).
    pub(crate) fn effective_settings() -> Value {
        let mut s: Value = serde_json::from_str(UPSTREAM_SETTINGS).unwrap();
        for (_, text) in SETTINGS_DROP_INS {
            let ops: Vec<Value> = serde_json::from_str(text).unwrap();
            for op in ops {
                let path = op["path"].as_str().unwrap();
                let (parent, last) = path.rsplit_once('/').unwrap();
                match op["op"].as_str().unwrap() {
                    "test" => assert_eq!(s.pointer(path).unwrap(), &op["value"], "{path}"),
                    "replace" => *s.pointer_mut(path).unwrap() = op["value"].clone(),
                    "remove" => {
                        let list = s.pointer_mut(parent).unwrap().as_array_mut().unwrap();
                        list.remove(last.parse().unwrap());
                    }
                    "add" if last == "-" => s
                        .pointer_mut(parent)
                        .unwrap()
                        .as_array_mut()
                        .unwrap()
                        .push(op["value"].clone()),
                    other => panic!("{other}"),
                }
            }
        }
        s
    }

    pub(crate) fn data() -> Value {
        let settings = effective_settings();
        let container = |kind: &str, name: &str, image: &str| {
            json!({
                "OCI": {"Annotations": {
                    TYPE_ANNOTATION: kind, NAME_ANNOTATION: name, IMAGE_ANNOTATION: image,
                }},
                "exec_commands": [],
            })
        };
        json!({
            "containers": [
                container("sandbox", "", "pause"),
                container("container", "web", &format!("nginx@sha256:{}", "ab".repeat(32))),
            ],
            "request_defaults": settings["request_defaults"],
            "cluster_config": settings["cluster_config"],
        })
    }

    #[test]
    fn vendored_files_are_genpolicy_4_1_0s() {
        // The tarball's files, so a vendored edit is a deliberate change to these digests.
        let sha = |s: &str| hex::encode(Sha256::digest(s.as_bytes()));
        // #82's drop-in, byte for byte (its testdata/SHA256SUMS); the rules and #82's rules patch
        // are checked in alpha_core::coco::policy.
        assert_eq!(
            sha(SETTINGS_DROP_INS[0].1),
            "da88e7dec050a4f30407bf60c81c5ba37e93beff0f3350909cbc56a877bd4247"
        );
        assert_eq!(
            sha(UPSTREAM_SETTINGS),
            "46bf9ac5460393f626ff2ed6fa2501ec5a82893da57c06e5c53a8f8e50e9dfa0"
        );
        // The rules fall back to refusal for every request the baseline names.
        for line in [
            "default ExecProcessRequest := false",
            "default ReadStreamRequest := false",
            "default CopyFileRequest := false",
            "default SetPolicyRequest := false",
            "default AllowRequestsFailingPolicy := false",
        ] {
            assert!(RULES.contains(&format!("\n{line}\n")), "{line}");
        }
    }

    #[test]
    fn settings_apply_the_baseline() {
        let s = effective_settings();
        let defaults = &s["request_defaults"];
        assert_eq!(
            defaults["ExecProcessRequest"]["allowed_commands"],
            json!([])
        );
        assert_eq!(defaults["ReadStreamRequest"], json!(false));
        assert_eq!(
            defaults["CreateContainerRequest"]["allow_env_regex"],
            json!(ALLOWED_ENV_REGEX)
        );
        let mounts = s["other_container"]["Mounts"].to_string();
        for token in TOKEN_MOUNTS {
            assert!(!mounts.contains(token), "{token}");
        }
        // Everything else is genpolicy's default.
        let upstream: Value = serde_json::from_str(UPSTREAM_SETTINGS).unwrap();
        assert_eq!(s["volumes"], upstream["volumes"]);
        assert_eq!(s["devices"], upstream["devices"]);
    }

    #[test]
    fn verify_accepts_the_baseline_and_lists_the_containers() {
        let verified = verify(&policy(&data())).unwrap();
        let names: Vec<_> = verified.containers.iter().map(|c| &c.name).collect();
        assert_eq!(names, ["web"]);
        assert!(verify(&(policy(&data()) + "\n")).is_ok());
    }

    #[test]
    fn verify_refuses_every_loosening() {
        type Change = fn(&mut Value);
        let cases: [(&str, Change); 12] = [
            ("ExecProcessRequest", |d| {
                d["request_defaults"]["ExecProcessRequest"]["allowed_commands"] = json!([["sh"]])
            }),
            ("ExecProcessRequest", |d| {
                d["request_defaults"]["ExecProcessRequest"]["regex"] = json!([".*"])
            }),
            ("ReadStreamRequest", |d| {
                d["request_defaults"]["ReadStreamRequest"] = json!(true)
            }),
            ("WriteStreamRequest", |d| {
                d["request_defaults"]
                    .as_object_mut()
                    .unwrap()
                    .remove("WriteStreamRequest");
            }),
            ("CopyFileRequest", |d| {
                d["request_defaults"]["CopyFileRequest"] = json!(["$(sfprefix)", "^/"])
            }),
            ("allow_env_regex", |d| {
                d["request_defaults"]["CreateContainerRequest"]["allow_env_regex"] =
                    json!(["^HOSTNAME=$(dns_label)$", "^.*$"])
            }),
            ("guest", |d| {
                d["cluster_config"]["guest_pull"] = json!(false)
            }),
            ("exec commands", |d| {
                d["containers"][1]["exec_commands"] = json!([["cat", "/etc/passwd"]])
            }),
            ("not pinned", |d| {
                d["containers"][1]["OCI"]["Annotations"][IMAGE_ANNOTATION] = json!("nginx:1")
            }),
            ("listed twice", |d| {
                let web = d["containers"][1].clone();
                d["containers"].as_array_mut().unwrap().push(web);
            }),
            ("no container", |d| {
                d["containers"].as_array_mut().unwrap().truncate(1);
            }),
            (
                "token",
                |d| {
                    d["containers"][1]["OCI"]["Mounts"] =
                        json!([{ "destination": "/var/run/secrets/kubernetes.io/serviceaccount" }])
                },
            ),
        ];
        for (why, change) in cases {
            let mut d = data();
            change(&mut d);
            let error = verify(&policy(&d)).unwrap_err();
            assert!(error.contains(why), "{why}: {error}");
        }
        // Edited rules, extra Rego after the data, and duplicate keys.
        let good = policy(&data());
        let edited = good.replacen(
            "default ExecProcessRequest := false",
            "default ExecProcessRequest := true",
            1,
        );
        assert!(verify(&edited).unwrap_err().contains("rules.rego"));
        assert!(verify(&format!("{good}\nExecProcessRequest := true\n")).is_err());
        let duplicate = good.replacen(
            "\"containers\": [",
            "\"containers\": [], \"containers\": [",
            1,
        );
        assert!(verify(&duplicate).is_err());
    }

    /// #82's fixtures (`testdata/agent-policy/*/policy.rego` on `prd02/13-malicious-host-full`),
    /// when `ALPHA_TEST_AGENT_POLICY` names a directory holding them: real genpolicy output under
    /// the same baseline, which `verify` accepts.
    #[test]
    fn verify_accepts_the_malicious_host_suites_policies() {
        let Some(dir) = std::env::var_os("ALPHA_TEST_AGENT_POLICY") else {
            return;
        };
        for pod in ["cpu-app", "gpu-model-server"] {
            let text =
                std::fs::read_to_string(PathBuf::from(&dir).join(pod).join("policy.rego")).unwrap();
            let verified = verify(&text).unwrap_or_else(|e| panic!("{pod}: {e}"));
            assert!(!verified.containers.is_empty());
        }
    }

    #[test]
    fn identity_parses_genpolicys_refusal() {
        let stderr = "ERROR: guest_pull is enabled for container 'alpha-runtime' using image 'docker.io/library/busybox@sha256:bd'. The generated policy expects UID=1000, GID=1000, AdditionalGids={0, 10, 1000}; containerd may not reproduce image-derived user/group values when image layers are pulled in the guest. Set explicit Kubernetes securityContext values, for example:\n";
        assert_eq!(
            identity(stderr),
            Some(GenpolicyError::Identity {
                container: "alpha-runtime".into(),
                uid: 1000,
                gid: 1000,
                groups: [0, 10, 1000].into(),
            })
        );
        assert_eq!(identity("thread 'main' panicked"), None);
    }

    #[tokio::test]
    async fn genpolicy_refuses_a_binary_of_another_digest() {
        let dir = TempDir::new().unwrap();
        let fake = dir.0.join("genpolicy");
        std::fs::write(&fake, b"#!/bin/sh\necho policy\n").unwrap();
        let g = Genpolicy {
            path: fake.clone(),
            sha256: GENPOLICY_SHA256.into(),
            defaults: None,
            timeout: Duration::from_secs(5),
        };
        match g.run("kind: Pod\n").await {
            Err(GenpolicyError::Failed(m)) => assert!(m.contains("not the pinned"), "{m}"),
            other => panic!("{other:?}"),
        }
        let missing = Genpolicy {
            path: dir.0.join("absent"),
            ..Genpolicy::pinned()
        };
        assert!(matches!(
            missing.run("kind: Pod\n").await,
            Err(GenpolicyError::Failed(_))
        ));
        // The right binary but release files of another digest beside it.
        let digest = hex::encode(Sha256::digest(std::fs::read(&fake).unwrap()));
        let defaults = dir.0.join("defaults");
        std::fs::create_dir(&defaults).unwrap();
        std::fs::write(defaults.join("rules.rego"), UPSTREAM_RULES).unwrap();
        std::fs::write(defaults.join("genpolicy-settings.json"), "{}").unwrap();
        let g = Genpolicy {
            path: fake,
            sha256: digest,
            defaults: Some(defaults),
            timeout: Duration::from_secs(5),
        };
        match g.run("kind: Pod\n").await {
            Err(GenpolicyError::Failed(m)) => {
                assert!(m.contains("genpolicy-settings.json has sha256"), "{m}")
            }
            other => panic!("{other:?}"),
        }
    }

    #[test]
    fn the_release_pins_are_the_embedded_files() {
        let sha = |s: &str| hex::encode(Sha256::digest(s.as_bytes()));
        assert_eq!(RELEASE_FILES[0].1, sha(UPSTREAM_RULES));
        assert_eq!(RELEASE_FILES[1].1, sha(UPSTREAM_SETTINGS));
    }
}
